import {test,expect} from '@playwright/test';
import {readFile,writeFile} from 'node:fs/promises';
import {zipSync} from 'fflate';
const app='/porting-pj/ed4/';
// Capture only the CC0 probe generated by scripts/phase9-7-audio.S.
for(const cycles of ['12000','24000'])for(const device of ['opl','pcm'])test(`cycles ${cycles} public ${device} Worker and WebAudio buffers`,async({page},info)=>{
 const variant='phase9-7';
 await page.addInitScript(()=>{
  const w=window as any;w.audioProbe={chunks:[],played:[],frequency:0,contextRate:0};
  const NativeWorker=window.Worker;
  window.Worker=class extends NativeWorker{constructor(url: string|URL,options?:WorkerOptions){super(url,options);this.addEventListener('message',e=>{
   if(e.data?.name==='ws-sound-init')w.audioProbe.frequency=e.data.props.freq;
   if(e.data?.name==='ws-sound-push'&&w.audioProbe.chunks.length<400)w.audioProbe.chunks.push(Array.from(e.data.props.samples));
  });}};
  const native=AudioBufferSourceNode.prototype.start;
  AudioBufferSourceNode.prototype.start=function(...args:Parameters<typeof native>){if(this.buffer&&w.audioProbe.played.length<400){w.audioProbe.contextRate=this.context.sampleRate;w.audioProbe.played.push({channels:this.buffer.numberOfChannels,rate:this.buffer.sampleRate,duration:this.buffer.duration,samples:Array.from(this.buffer.getChannelData(0)),at:args[0],now:this.context.currentTime});}return native.apply(this,args);};
 });
 await page.route('**/test-program.zip',async r=>r.fulfill({contentType:'application/zip',body:Buffer.from(zipSync({'ED4TEST.COM':new Uint8Array(Buffer.from((await readFile('tests/fixtures/phase9-7-audio.b64','utf8')).trim(),'base64'))}))}));
 await page.goto(app);page.on('dialog',d=>void d.accept());
 await page.locator('#advanced-settings').evaluate(e=>(e as HTMLDetailsElement).open=true);await page.locator('#demo').click();await expect(page.locator('#status')).toContainText('공개 테스트 준비 완료');
 await page.locator('#boot-open').click();await page.locator('#boot-engine').selectOption(variant);await page.locator('#boot-cycles').fill(cycles);await page.locator('#boot-start').click();
 await expect(page.locator('#logs')).toContainText('AUDIO_READY');
 await page.evaluate(()=>{(window as any).audioProbe.chunks=[];(window as any).audioProbe.played=[];});
 await page.keyboard.press(device==='opl'?'o':'p');await expect(page.locator('#logs')).toContainText('AUDIO_DONE');
 await page.waitForTimeout(250);
 const data=await page.evaluate(()=>(window as any).audioProbe);expect(data.frequency).toBe(22050);expect(data.chunks.flat().some((v:number)=>Math.abs(v)>0.005)).toBe(true);
 const dir=cycles;
 expect(data.played.every((b:any)=>b.channels===(variant==='phase9-7'?1:2))).toBe(true);
 if(variant==='phase9-7'){expect(data.played.length).toBe(data.chunks.length);for(let i=0;i<data.chunks.length;i++)expect(data.played[i].samples).toEqual(data.chunks[i]);}
 await writeFile(`artifacts/phase9-8/${dir}-${device}.json`,JSON.stringify(data));
 await writeFile(info.outputPath('capture.json'),JSON.stringify({device,...data}));
 await page.keyboard.press('q');await page.locator('#stop').click();await expect(page.locator('#run-state')).toHaveText('종료됨');
});
